package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParseException;
import com.fasterxml.jackson.core.ObjectCodec;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactory;
import com.fasterxml.jackson.core.sym.*;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import java.util.Arrays;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class UTF8StreamJsonParser__parseFieldName_TriageGen0Test {

    private UTF8StreamJsonParser parser;
    private byte[] inputBuffer;
    private IOContext ioc;
    private BytesToNameCanonicalizer sym;
    private ObjectCodec codec;

    private static final int INT_QUOTE = 34;

    @Before
    public void setUp() throws Exception {
        ioc = Mockito.mock(IOContext.class);
        codec = Mockito.mock(ObjectCodec.class);
        sym = Mockito.mock(BytesToNameCanonicalizer.class);

        // Initial dummy buffer
        inputBuffer = new byte[128];

        // Create parser using a real factory to get an instance, 
        // then we will manipulate its protected fields via reflection.
        JsonFactory factory = new JsonFactory();
        parser = new UTF8StreamJsonParser(ioc, 0, new ByteArrayInputStream(new byte[0]), codec, sym, inputBuffer, 0, 0, false);
    }

    private void setParserState(byte[] buffer, int start, int end, int ptr) throws Exception {
        this.inputBuffer = buffer;
        setField(parser, "_inputBuffer", buffer);
        setField(parser, "_inputEnd", end);
        setField(parser, "_inputPtr", ptr);

        // Mocking _icLatin1 which is needed for the logic
        int[] codes = new int[256];
        // In Jackson, _icLatin1 is a lookup table where 0 means it's a Latin1 char
        // We assume a standard setup where we don't need to fill it for basic ASCII tests
        setField(parser, "_icLatin1", codes);
    }

    private void setField(Object obj, String fieldName, Object value) throws Exception {
        Field field = obj.getClass().getDeclaredField(fieldName);
        field.setAccessible(true);
        field.set(obj, value);
    }

    private Name invokeParseFieldName(int i) throws Exception {
        Method method = parser.getClass().getDeclaredMethod("_parseFieldName", int.class);
        method.setAccessible(true);
        return (Name) method.invoke(parser, i);
    }

    @Test
    public void testHandleOddName() throws Exception {
        setParserState(new byte[]{1, 2, 3}, 0, 3, 0);
        // If i != INT_QUOTE, it calls _handleOddName
        // We use a value that is definitely not 34
        Name result = invokeParseFieldName(1);
        assertNotNull(result);
    }

    @Test
    public void testSlowParseNameDueToBounds() throws Exception {
        // (ptr + 9) > end => (0 + 9) > 5
        setParserState(new byte[]{34, 97, 98, 99, 100}, 0, 5, 0);
        // This should trigger slowParseName via reflection if we could mock it, 
        // but here we just ensure it doesn't crash and follows the branch.
        // Since we can't easily mock protected methods of the class under test without PowerMock,
        // we verify the branch logic.
        try {
            invokeParseFieldName(INT_QUOTE);
        } catch (Exception e) {
            // slowParseName might throw exception because buffer is too small, which is fine for branch coverage
        }
    }

    @Test
    public void testEmptyName() throws Exception {
        // q == INT_QUOTE case (the "" case)
        // The code checks: int q = input[_inputPtr++] & 0xFF; if (q == INT_QUOTE) return ...
        setParserState(new byte[]{34, 34}, 0, 2, 0);
        Mockito.when(sym.getEmptyName()).thenReturn(Mockito.mock(Name.class));

        Name result = invokeParseFieldName(INT_QUOTE);
        assertNotNull(result);
    }

    @Test
    public void testParseNameBranches() throws Exception {
        // Test various lengths of names to hit different nested if/else branches

        // Case 1: Length 1 (q, then i=QUOTE)
        // input: "a" -> 34, 97, 34
        setParserState(new byte[]{34, 97, 34}, 0, 3, 0);
        invokeParseFieldName(INT_QUOTE);

        // Case 2: Length 2 (q, i, then i=QUOTE)
        // input: "ab" -> 34, 97, 98, 34
        setParserState(new byte[]{34, 97, 98, 34}, 0, 4, 0);
        invokeParseFieldName(INT_QUOTE);

        // Case 3: Length 3
        // input: "abc" -> 34, 97, 98, 99, 34
        setParserState(new byte[]{34, 97, 98, 99, 34}, 0, 5, 0);
        invokeParseFieldName(INT_QUOTE);

        // Case 4: Length 4 (Hits parseMediumName)
        // input: "abcd" -> 34, 97, 98, 99, 100, 34
        setParserState(new byte[]{34, 97, 98, 99, 100, 34}, 0, 6, 0);
        invokeParseFieldName(INT_QUOTE);
    }

    @Test
    public void testInvalidCharBranch() throws Exception {
        // Test the branch: return parseName(0, q, 0);
        // This happens if codes[q] != 0 and q != INT_QUOTE
        int[] codes = new int[256];
        codes[97] = 1; // Mark 'a' as non-Latin1 (e.g., a multi-byte start)
        setParserState(new byte[]{34, 97}, 0, 2, 0);
        setField(parser, "_icLatin1", codes);

        invokeParseFieldName(INT_QUOTE);
    }

    @Test
    public void testParseNameBranchesExtended() throws Exception {
        // Testing the "return parseName(q, i, X)" paths where i is not QUOTE

        // Length 1: "a" -> 34, 97, 34 (Handled in testParseNameBranches)
        // But we need to hit the 'else' of 'if (i == INT_QUOTE)'

        // Length 1: "a" where 'a' is not QUOTE
        setParserState(new byte[]{34, 97, 98}, 0, 3, 0); // i becomes 98 (b), not 34
        invokeParseFieldName(INT_QUOTE);

        // Length 2: "ab"
        setParserState(new byte[]{34, 97, 98, 99}, 0, 4, 0); 
        invokeParseFieldName(INT_QUOTE);

        // Length 3: "abc"
        setParserState(new byte[]{34, 97, 98, 99, 100}, 0, 5, 0);
        invokeParseFieldName(INT_QUOTE);
    }
}
